effect.shader:
void main() {
vec2 uv = acScreenNorm;
vec4 base = texture2DCv(inputImg.texture, uv);
vec2 offsetR = vec2(amount, amount);
vec2 offsetB = vec2(-amount, -amount);
float r = texture2DCv(inputImg.texture, uv + offsetR * blur).r;
float g = base.g;
float b = texture2DCv(inputImg.texture, uv + offsetB * blur).b;
gl_FragColor = vec4(r, g, b, base.a);
}
